{"command":"python3 -c "
import csv

# Test RFC 4180 compliance
with open('outputs/t02_eurostat_raw.csv', 'r', encoding='utf-8', newline='') as f:
    reader = csv.reader(f)
    rows = list(reader)

print(f'Total rows (including header): {len(rows)}')
header = rows[0]
print(f'Header fields: {len(header)}')

# Check each row has correct number of fields
for i, row in enumerate(rows):
    if len(row) != len(header):
        print(f'Row {i}: {len(row)} fields (expected {len(header)})')

# Check quoting - fields with commas should be quoted
for row in rows[1:]:
    for field in row:
        if ',' in field and not (field.startswith('\"') and field.endswith('\"')):
            print(f'Unquoted field with comma: {field}')
        if '\"' in field[1:-1] if len(field) > 2 else False:
            print(f'Field with internal quote: {field}')

print('RFC 4180 compliance check passed')
""}
